/**
 * JSON persistence for blocked actions, approvals, loop control, and budget.
 * Lives under shadow-ceo-authority/repository as required by WS4.
 */

import { randomUUID } from "node:crypto";
import fs from "node:fs";
import path from "node:path";

import { resolveShadowCeoAuthorityDir } from "../../shadow-ceo-integration/durable-paths.js";
import { defaultBudgetEnvelope } from "../budget.js";
import { createInitialLoopState } from "../gate.js";
import type {
  ApprovalRequest,
  BlockedActionRecord,
  BudgetEnvelope,
  OperatingLoopState,
} from "../types.js";

export type AuthorityStoreFile = {
  blocked: BlockedActionRecord[];
  approvals: ApprovalRequest[];
  loop: OperatingLoopState;
  budget: BudgetEnvelope;
};

let captureFenceHeld = false;

/** Stable shared exclusion for cooperating processes. A crashed owner leaves a
 * fail-closed lock; never infer expiry or steal a possibly active capture. */
function acquireSharedAuthorityExclusion(baseDir?: string): () => void {
  const target = resolveStorePath(baseDir);
  const parent = path.dirname(target);
  if (fs.realpathSync(parent) !== path.resolve(parent)) throw new Error("AUTHORITY_JSON_LOCK_PATH_UNSAFE");
  const lock = target + ".capture-write-lock";
  try { fs.mkdirSync(lock, { mode: 0o700 }); }
  catch (error) {
    if ((error as NodeJS.ErrnoException).code === "EEXIST") throw new Error("AUTHORITY_JSON_SHARED_CAPTURE_BUSY");
    throw error;
  }
  const identity = fs.lstatSync(lock);
  let released = false;
  return () => {
    if (released) return;
    const current = fs.lstatSync(lock);
    if (!current.isDirectory() || current.isSymbolicLink() || current.dev !== identity.dev || current.ino !== identity.ino)
      throw new Error("AUTHORITY_JSON_LOCK_IDENTITY_CHANGED");
    fs.rmdirSync(lock);
    released = true;
  };
}

/** Captures and atomic saves use the same stable lock across updated processes.
 * This does not fence older binaries or replace whole-topology exclusion. */
export function acquireAuthorityJsonCaptureFence(baseDir?: string): () => void {
  if (captureFenceHeld) throw new Error("AUTHORITY_JSON_CAPTURE_BUSY");
  const releaseShared = acquireSharedAuthorityExclusion(baseDir);
  captureFenceHeld = true;
  let released = false;
  return () => {
    if (released) return;
    releaseShared();
    released = true;
    captureFenceHeld = false;
  };
}

export function resolveStorePath(baseDir?: string): string {
  const dir = baseDir ?? resolveShadowCeoAuthorityDir();
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  return path.join(dir, "authority-store.json");
}

export function emptyAuthorityStore(): AuthorityStoreFile {
  return {
    blocked: [],
    approvals: [],
    loop: createInitialLoopState(),
    budget: defaultBudgetEnvelope(),
  };
}

export function loadAuthorityStore(baseDir?: string): AuthorityStoreFile {
  const p = resolveStorePath(baseDir);
  if (!fs.existsSync(p)) return emptyAuthorityStore();
  try {
    const value: unknown = JSON.parse(fs.readFileSync(p, "utf8"));
    if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("not an authority object");
    const store = value as AuthorityStoreFile;
    if (!Array.isArray(store.blocked) || !Array.isArray(store.approvals) ||
        !store.loop || typeof store.loop.running !== "boolean" ||
        !store.budget || store.budget.source !== "deterministic_state" ||
        !store.blocked.every(row => row && row.decision === "BLOCKED") ||
        !store.approvals.every(row => row && row.source === "deterministic_store")) {
      throw new Error("invalid authority records");
    }
    return store;
  } catch (error) {
    throw new Error("SHADOW_CEO_AUTHORITY_UNREADABLE: refusing to replace existing authority state", { cause: error });
  }
}

export function saveAuthorityStore(
  store: AuthorityStoreFile,
  baseDir?: string,
): void {
  writeAuthorityStore(() => store, baseDir);
}

/** Evaluate the mutation only while holding the same exclusion used by capture. */
function writeAuthorityStore(
  resolveNext: () => AuthorityStoreFile,
  baseDir?: string,
): void {
  if (captureFenceHeld) throw new Error("AUTHORITY_JSON_CAPTURE_FENCED");
  const p = resolveStorePath(baseDir);
  const releaseShared = acquireSharedAuthorityExclusion(baseDir);
  const temp = `${p}.tmp-${process.pid}-${randomUUID()}`;
  try {
    const store = resolveNext();
    const fd = fs.openSync(temp, "wx", 0o600);
    try {
      fs.writeFileSync(fd, JSON.stringify(store, null, 2), "utf8");
      fs.fsyncSync(fd);
    } finally {
      fs.closeSync(fd);
    }
    fs.renameSync(temp, p);
    if (process.platform !== "win32") {
      const parent = fs.openSync(path.dirname(p), "r");
      try { fs.fsyncSync(parent); } finally { fs.closeSync(parent); }
    }
  } finally {
    try { fs.rmSync(temp, { force: true }); } finally { releaseShared(); }
  }
}

export function persistBlockedAction(
  blocked: BlockedActionRecord,
  baseDir?: string,
): BlockedActionRecord {
  writeAuthorityStore(() => {
    const store = loadAuthorityStore(baseDir);
    store.blocked.push(blocked);
    return store;
  }, baseDir);
  return blocked;
}

export function persistApprovalRequest(
  approval: ApprovalRequest,
  baseDir?: string,
): ApprovalRequest {
  writeAuthorityStore(() => {
    const store = loadAuthorityStore(baseDir);
    store.approvals.push(approval);
    return store;
  }, baseDir);
  return approval;
}

export function persistLoopState(
  loop: OperatingLoopState,
  baseDir?: string,
): OperatingLoopState {
  writeAuthorityStore(() => {
    const store = loadAuthorityStore(baseDir);
    store.loop = loop;
    return store;
  }, baseDir);
  return loop;
}

export function listBlockedActions(baseDir?: string): BlockedActionRecord[] {
  return loadAuthorityStore(baseDir).blocked;
}

import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawn, spawnSync } from 'node:child_process';
import { once } from 'node:events';
import { test } from 'node:test';
import { acquireAuthorityJsonCaptureFence, emptyAuthorityStore, loadAuthorityStore, resolveStorePath, saveAuthorityStore } from '../../orchestration/shadow-ceo-authority/repository/json-authority-store.js';
const url = new URL('../../orchestration/shadow-ceo-authority/repository/json-authority-store.ts', import.meta.url).href;
const prefix = `import fs from 'node:fs'; import * as m from ${JSON.stringify(url)};`;
function invocation(kind: string, root: string) {
  const args = kind === 'BlockedAction' ? "{id:'a',decision:'BLOCKED'}" : kind === 'ApprovalRequest' ? "{id:'a',source:'deterministic_store'}" : "{...m.emptyAuthorityStore().loop,running:false,reason:'updated'}";
  return `m.persist${kind}(${args},${JSON.stringify(root)});`;
}
function run(code: string) { return spawnSync(process.execPath, ['--import','tsx','--input-type=module','-e',prefix+code], {encoding:'utf8',timeout:15000}); }
for (const kind of ['BlockedAction','ApprovalRequest','LoopState']) {
  test(`${kind} locks the full read-modify-write and preserves competing records`, {timeout:30000}, async t => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(),'authority-atomic-'));
    t.after(()=>fs.rmSync(root,{recursive:true,force:true}));
    saveAuthorityStore(emptyAuthorityStore(),root);
    // Pause A just after the snapshot read. Previously B could commit here and
    // A would subsequently overwrite B. Updated writers must refuse and retry.
    const code = prefix+`const original=fs.readFileSync;let held=false;
      fs.readFileSync=function(file,...args){const result=original.call(this,file,...args);
      if(file===${JSON.stringify(resolveStorePath(root))}&&!held){held=true;fs.writeSync(1,'snapshot-read\\n');fs.readSync(0,Buffer.alloc(1),0,1,null);}return result;};`+invocation(kind,root);
    const child=spawn(process.execPath,['--import','tsx','--input-type=module','-e',code],{stdio:['pipe','pipe','pipe']});
    t.after(()=>child.kill('SIGKILL'));
    let errors='';child.stderr.on('data',chunk=>{errors+=chunk;});
    const exit=once(child,'exit');
    assert.match(String((await once(child.stdout,'data'))[0]),/snapshot-read/);
    const other=`m.persistApprovalRequest({id:'b',source:'deterministic_store'},${JSON.stringify(root)});`;
    const refused=run(other);
    assert.notEqual(refused.status,0);assert.match(refused.stderr,/AUTHORITY_JSON_SHARED_CAPTURE_BUSY/);
    child.stdin.end('x');assert.equal((await exit)[0],0,errors);
    const retry=run(other);assert.equal(retry.status,0,retry.stderr);
    const result=loadAuthorityStore(root);
    assert.ok(result.approvals.some(row=>(row as unknown as {id:string}).id==='b'));
    if(kind==='BlockedAction')assert.equal(result.blocked.length,1);
    if(kind==='ApprovalRequest')assert.equal(result.approvals.length,2);
    if(kind==='LoopState')assert.equal((result.loop as unknown as {reason:string}).reason,'updated');
  });
}
test('all mutators refuse cross-process capture without changing bytes',()=>{
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'authority-capture-'));
  try{
    saveAuthorityStore(emptyAuthorityStore(),root);
    const before=fs.readFileSync(resolveStorePath(root),'utf8');
    const release=acquireAuthorityJsonCaptureFence(root);
    try{for(const kind of ['BlockedAction','ApprovalRequest','LoopState']){
      const result=run(invocation(kind,root));assert.notEqual(result.status,0);
      assert.match(result.stderr,/AUTHORITY_JSON_SHARED_CAPTURE_BUSY/);
      assert.equal(fs.readFileSync(resolveStorePath(root),'utf8'),before);
    }}finally{release();}
  }finally{fs.rmSync(root,{recursive:true,force:true});}
});

